from textlesson import build
S=dict(cls=7,subj="maths",subj_file="maths")
build(dict(S,ch="geometric-twins",topic="congruent-shapes",name_en="Congruent shapes",name_ta="சர்வசம வடிவங்கள்",
 objectives=["Say when two shapes are congruent","Use side-angle-side and side-side-side to test triangles"],
 story=("The twin stamps","Divya made two rubber stamps from the same mould. When she pressed them on paper one over the other, the prints matched exactly.\n\"They are twins,\" she said. \"In maths we call such shapes congruent.\""),
 explain=["Two shapes are congruent if one fits exactly over the other, matching in size and shape. They may be turned, flipped or slid. Matching sides and angles are called corresponding parts and they are equal.","Two triangles are congruent if three sides of one equal the three sides of the other (SSS). They are also congruent if two sides and the angle between them are equal (SAS), or if two angles and the side between them are equal (ASA).","Congruence is useful in making identical parts for machines, tiles and buildings. Shapes with the same shape but different sizes are not congruent."],
 terms=["congruent","corresponding parts","SSS","SAS","ASA"],
 narr=[("Two shapes are congruent if one fits exactly over the other.","congruent shapes"),("Matching sides and angles are equal.","corresponding parts"),("Triangles are congruent if three sides are equal, or two sides and the angle between them are equal.","SSS and SAS"),("Same shape but different size is not congruent.","size matters")],
 ex=("Triangle ABC has sides 3, 4, 5 cm and triangle PQR has sides 5, 3, 4 cm. Are they congruent?",[("Write the sides in order: 3, 4, 5 and 3, 4, 5.","The three sides match."),("All three sides of one equal the three sides of the other.","This is SSS."),("So the triangles are congruent.","The order of naming does not matter.")]),
 tb=("A friend says all squares are congruent. How will you correct this?",["Squares can have different side lengths.","Only squares of the same side are congruent."],["Confusing similar shape with congruent."]),
 summary=["Congruent shapes match exactly in size and shape.","Triangles: SSS, SAS and ASA tests.","Same shape but different size is not congruent."],
 q=[("mcq",1,"r1-def","Two shapes are congruent if they","fit exactly over each other",[("look similar","Size must match too."),("have the same colour","Colour is not relevant.")],"They match in size and shape."),
    ("tf",1,"r1-flip","A flipped shape can still be congruent.",True,"True."),
    ("mcq",2,"r2-sss","If three sides of one triangle equal three sides of another, the triangles are","congruent",[("not congruent","They are congruent by SSS."),("always right-angled","Not necessarily.")],"SSS test."),
    ("tf",2,"r2-sq","All squares are congruent to each other.",False,"False."),
    ("mcq",3,"r3-sas","In SAS the angle must be","between the two sides",[("outside the sides","It must be the included angle."),("any angle","It must be included.")],"Included angle."),
    ("short",3,"r3-test","Name one test for congruent triangles.",["sss","sas","asa","side side side","side angle side","angle side angle"],"SSS, SAS and ASA."),
    ("mcq",4,"r4-use","Congruence is useful for","making identical parts",[("making different sizes","Congruent means same."),("changing colours","Not related.")],"Tiles and machine parts."),
    ("tf",4,"r4-corr","Corresponding parts of congruent triangles are equal.",True,"True.")]))
build(dict(S,ch="operations-with-integers",topic="adding-and-subtracting-integers",name_en="Adding and subtracting integers",name_ta="முழுக்களைக் கூட்டலும் கழித்தலும்",
 objectives=["Add and subtract positive and negative integers","Use the number line"],
 story=("The lift","A lift in a building goes up to floors 1, 2, 3 and down to basement levels −1 and −2. Karan was on floor 2 and went down 5 floors.\n\"Where am I?\" he asked. His sister drew a number line. \"At −3, in the basement.\""),
 explain=["Integers are the whole numbers and their negatives: ..., −3, −2, −1, 0, 1, 2, 3, ... On the number line numbers to the right are bigger. Adding a positive number moves to the right and adding a negative number moves to the left.","Adding integers: with the same signs add the numbers and keep the sign, so (−3) + (−4) = −7. With different signs subtract the smaller from the larger and keep the sign of the larger: 5 + (−8) = −3.","Subtracting an integer is the same as adding its opposite: 5 − (−3) = 5 + 3 = 8 and 2 − 6 = 2 + (−6) = −4. The opposite of a number has the same size but the other sign."],
 terms=["integer","negative number","number line","opposite"],
 narr=[("Integers are whole numbers and their negatives. On the number line right means bigger.","integers"),("To add integers with the same sign, add the numbers and keep the sign.","same signs"),("With different signs, subtract the smaller from the larger and keep the sign of the larger.","different signs"),("Subtracting an integer is adding its opposite.","subtract = add opposite")],
 ex=("Find 5 − (−3).",[("Subtracting an integer means adding its opposite.","The opposite of −3 is 3."),("So 5 − (−3) becomes 5 + 3.","Now add."),("5 + 3 = 8. So the answer is 8.","On the number line we move right.")]),
 tb=("A friend says (−3) + (−4) = 1. How will you correct this?",["Both numbers are negative, so we add 3 and 4 to get 7 and keep the negative sign.","The answer is −7."],["Mixing up the signs."]),
 summary=["Same signs: add and keep the sign.","Different signs: subtract and keep the sign of the larger.","Subtract by adding the opposite."],
 q=[("mcq",1,"r1-add","(−3) + (−4) =","−7",[("7","The sign is negative."),("1","Wrong.")],"3 + 4 = 7 with a negative sign."),
    ("tf",1,"r1-line","On the number line, numbers to the right are bigger.",True,"True."),
    ("mcq",2,"r2-diff","5 + (−8) =","−3",[("3","The larger number is negative."),("13","Wrong.")],"8 − 5 = 3 with a negative sign."),
    ("tf",2,"r2-neg","−2 is greater than −5.",True,"True."),
    ("mcq",3,"r3-sub","5 − (−3) =","8",[("2","That subtracts 3."),("−8","Wrong sign.")],"Add the opposite."),
    ("short",3,"r3-calc","Find 2 − 6.",["-4","−4"],"2 + (−6) = −4."),
    ("mcq",4,"r4-opp","The opposite of −7 is","7",[("−7","That is the same."),("0","That is zero.")],"Same size, other sign."),
    ("tf",4,"r4-zero","Zero is neither positive nor negative.",True,"True.")]))
build(dict(S,ch="finding-common-ground",topic="hcf-and-lcm",name_en="HCF and LCM",name_ta="பொ.கா.பெ. மற்றும் பொ.ம.சி.",
 objectives=["Find the HCF and LCM of two numbers","Solve simple problems with them"],
 story=("The tiles","Ria wanted to cover a floor 12 feet by 18 feet with square tiles of the same size without cutting any. \"What is the biggest tile that fits?\" she asked.\nHer father found the largest number that divides both 12 and 18. It was 6, so the tile was 6 feet by 6 feet."),
 explain=["The highest common factor (HCF) of two numbers is the largest number that divides both exactly. The factors of 12 are 1, 2, 3, 4, 6, 12 and of 18 are 1, 2, 3, 6, 9, 18. The common factors are 1, 2, 3, 6, so the HCF is 6.","The lowest common multiple (LCM) is the smallest number that is a multiple of both. The multiples of 4 are 4, 8, 12, 16 ... and of 6 are 6, 12, 18 ... The first common multiple is 12, so the LCM of 4 and 6 is 12.","We can find the HCF and LCM using prime factorisation. HCF takes the common prime factors with the smallest powers and LCM takes all prime factors with the largest powers. For two numbers, HCF × LCM = their product."],
 terms=["HCF","LCM","factor","multiple","prime factorisation"],
 narr=[("The HCF is the largest number that divides both numbers.","HCF"),("The LCM is the smallest number that is a multiple of both.","LCM"),("The HCF of 12 and 18 is 6. The LCM of 4 and 6 is 12.","examples"),("For two numbers, HCF times LCM equals their product.","product rule")],
 ex=("Find the HCF and LCM of 12 and 18.",[("12 = 2 × 2 × 3 and 18 = 2 × 3 × 3.","Prime factorise both."),("HCF takes the common factors 2 × 3 = 6.","LCM takes 2 × 2 × 3 × 3 = 36."),("So the HCF is 6 and the LCM is 36. Check: 6 × 36 = 216 = 12 × 18.","The product rule works.")]),
 tb=("A friend says the LCM of 4 and 6 is 24 because 4 × 6 = 24. How will you correct this?",["24 is a common multiple, but 12 is smaller and also a multiple of both.","The LCM is the smallest, which is 12."],["Using the product as the LCM."]),
 summary=["HCF is the largest common factor.","LCM is the smallest common multiple.","HCF × LCM = product of the two numbers."],
 q=[("mcq",1,"r1-hcf","The HCF of 12 and 18 is","6",[("3","3 is a factor, not the highest."),("36","That is the LCM.")],"Largest common factor."),
    ("tf",1,"r1-lcm","The LCM of 4 and 6 is 12.",True,"True."),
    ("mcq",2,"r2-lcm2","The LCM of 3 and 5 is","15",[("8","That is the sum."),("1","That is the HCF.")],"3 × 5 since they share no factor."),
    ("tf",2,"r2-hcf","The HCF of two numbers can be larger than either number.",False,"False."),
    ("mcq",3,"r3-prod","For 12 and 18, HCF × LCM =","216",[("36","That is the LCM."),("6","That is the HCF.")],"It equals 12 × 18."),
    ("short",3,"r3-find","Find the HCF of 8 and 12.",["4"],"Common factors 1, 2, 4."),
    ("mcq",4,"r4-tile","The biggest square tile to cover 12 ft by 18 ft is","6 ft",[("3 ft","Smaller than the biggest."),("36 ft","Bigger than the floor width.")],"Use the HCF."),
    ("tf",4,"r4-mult","The LCM is a multiple of both numbers.",True,"True.")]))
build(dict(S,ch="another-peek-beyond-the-point",topic="operations-with-decimals",name_en="Operations with decimals",name_ta="தசமங்களில் செயல்கள்",
 objectives=["Add, subtract and multiply decimals","Divide a decimal by a whole number"],
 story=("At the market","Imran bought 2.5 kg of rice at ₹42.40 per kilogram. \"How much must I pay?\" he asked the shopkeeper.\nThe shopkeeper multiplied 42.40 by 2.5 on paper. \"₹106,\" he said."),
 explain=["To add or subtract decimals, line up the decimal points so that tenths are under tenths and hundredths under hundredths, then add or subtract as with whole numbers. For example 12.5 + 3.75 = 16.25.","To multiply decimals, multiply as if there were no decimal points and then place the point so that the answer has as many decimal places as the two numbers together. For 2.5 × 1.2 there are 2 decimal places in all, 25 × 12 = 300, so the answer is 3.00 = 3.","To divide a decimal by a whole number, divide as usual and put the decimal point in the answer above the point in the number: 7.5 ÷ 5 = 1.5. Multiplying by 10 moves the point one place right and dividing by 10 moves it one place left."],
 terms=["decimal places","place value","multiply","divide"],
 narr=[("To add or subtract decimals, line up the decimal points.","line up points"),("To multiply decimals, multiply as whole numbers, then count the decimal places in total.","multiply"),("To divide by a whole number, divide as usual and place the point above.","divide"),("Multiplying by ten moves the point one place right.","times ten")],
 ex=("Find 2.5 × 1.2.",[("Ignore the points: 25 × 12 = 300.","Multiply as whole numbers."),("There is one decimal place in each number, so two in all.","Count the places."),("Put the point so that the answer has two places: 3.00, which is 3.","So 2.5 × 1.2 = 3.")]),
 tb=("A friend says 0.4 × 0.3 equals 1.2. How will you explain the mistake?",["4 × 3 = 12 and there are two decimal places.","So the answer is 0.12."],["Forgetting to place the decimal point."]),
 summary=["Line up decimal points to add and subtract.","Multiply as whole numbers and count total decimal places.","Divide by a whole number and put the point straight above."],
 q=[("mcq",1,"r1-add","12.5 + 3.75 =","16.25",[("15.25","Wrong."),("16.00","Wrong.")],"Line up the points."),
    ("tf",1,"r1-line","When adding decimals we line up the decimal points.",True,"True."),
    ("mcq",2,"r2-mul","0.4 × 0.3 =","0.12",[("1.2","Wrong place."),("0.012","Too many places.")],"4 × 3 = 12 with two places."),
    ("tf",2,"r2-ten","Multiplying a decimal by 10 moves the point one place to the right.",True,"True."),
    ("mcq",3,"r3-div","7.5 ÷ 5 =","1.5",[("15","Wrong."),("0.15","Wrong place.")],"75 ÷ 5 = 15 with the point placed."),
    ("short",3,"r3-calc","Find 2.5 × 4.",["10","10.0"],"2.5 × 4 = 10."),
    ("mcq",4,"r4-sub","5.0 − 2.35 =","2.65",[("3.65","Wrong."),("2.35","Wrong.")],"Line up points and subtract."),
    ("tf",4,"r4-div10","Dividing by 10 moves the decimal point one place left.",True,"True.")]))
